import 'dart:math' as math;

import 'lesson_data.dart';

/// Expanded, topic-based offline curriculum. Existing lesson IDs remain stable;
/// lesson IDs are stable so saved progress survives app updates.
class ExpandedCourseData {
  ExpandedCourseData._();

  static final List<Unit> units = [..._topics, ..._newTopics].map(_buildUnit).toList();

  static Unit _buildUnit(_Topic topic) {
    final lessons = <Lesson>[];
    final uniqueWords = <_Word>[];
    final seenWords = <String>{};
    for (final word in topic.words) {
      final key = word.en.trim().toLowerCase();
      if (key.isNotEmpty && seenWords.add(key)) uniqueWords.add(word);
    }
    const wordsPerLesson = 3;
    final lessonCount = (uniqueWords.length / wordsPerLesson).ceil();
    for (var i = 0; i < lessonCount; i++) {
      final words = uniqueWords.skip(i * wordsPerLesson).take(wordsPerLesson).toList();
      final vocabulary = words.map((word) => VocabularyItem(
        english: word.en,
        pronunciation: word.ipa,
        farsi: word.fa,
        exampleEn: word.example,
        exampleFa: word.exampleFa,
        cefrLevel: topic.level,
        category: topic.id,
      )).toList();
      final meanings = words.map((word) => word.fa).toList();
      final exercises = <Exercise>[];
      for (var j = 0; j < words.length; j++) {
        final word = words[j];
        final options = <String>{word.fa, ...meanings.where((m) => m != word.fa), 'نمی‌دانم'}.toList();
        final optionSeed = topic.id.codeUnits.fold<int>(i + j, (sum, unit) => sum + unit);
        options.shuffle(math.Random(optionSeed));
        final questionVariant = (i + j) % 3;
        final question = questionVariant == 0
            ? 'What does "${word.en}" mean?'
            : questionVariant == 1
                ? 'In this sentence, what does "${word.en}" mean: "${word.example}"?'
                : 'Choose the closest meaning of "${word.en}" as used in the example.';
        final questionFarsi = questionVariant == 0
            ? 'معنی «${word.en}» کدام است؟'
            : questionVariant == 1
                ? 'در جملهٔ «${word.example}»، واژهٔ «${word.en}» چه معنایی دارد؟'
                : 'با توجه به مثال، نزدیک‌ترین معنی «${word.en}» کدام است؟';
        exercises.add(Exercise(
          id: '${topic.id}_l${i + 1}_e${j + 1}',
          type: ExerciseType.multipleChoice,
          question: question,
          questionFarsi: questionFarsi,
          options: options,
          correctAnswer: word.fa,
          explanationFarsi: '«${word.en}» یعنی «${word.fa}». نمونه: ${word.example} — ${word.exampleFa}',
          exampleEn: word.example,
          exampleFa: word.exampleFa,
          xpReward: 5,
        ));
      }
      lessons.add(Lesson(
        id: '${topic.id}_l${i + 1}',
        title: topic.lessonTitles[i % topic.lessonTitles.length] +
            (i >= topic.lessonTitles.length ? ' — Practice ${i + 1}' : ''),
        titleFarsi: topic.lessonTitlesFa[i % topic.lessonTitlesFa.length] +
            (i >= topic.lessonTitlesFa.length ? ' — تمرین تکمیلی ${i + 1}' : ''),
        cefrLevel: topic.level,
        vocabulary: vocabulary,
        exercises: exercises,
        xpReward: 30,
        emoji: topic.lessonEmojis[i % topic.lessonEmojis.length],
        objectivesFarsi: [topic.objectives[i % topic.objectives.length] + (i >= topic.objectives.length ? ' در جمله‌ها و موقعیت‌های واقعی به کار ببری.' : '')],
        skillFocus: const ['vocabulary', 'reading', 'sentence building'],
        estimatedMinutes: 10,
      ));
    }
    return Unit(
      id: topic.id,
      title: topic.title,
      titleFarsi: topic.titleFa,
      cefrLevel: topic.level,
      emoji: topic.emoji,
      lessons: lessons,
    );
  }
}

class _Topic {
  final String id, level, title, titleFa, emoji;
  final List<String> lessonTitles, lessonTitlesFa, lessonEmojis, objectives;
  final List<_Word> words;
  const _Topic(this.id, this.level, this.title, this.titleFa, this.emoji,
      this.lessonTitles, this.lessonTitlesFa, this.lessonEmojis, this.objectives, this.words,
      );
}

class _Word {
  final String en, fa, ipa, example, exampleFa;
  const _Word(this.en, this.fa, this.ipa, this.example, this.exampleFa);
}

